const items = $input.all();

const MY_EMAIL = 'mohanrajramkumar56@gmail.com';

function getHeader(headers, name) {
  if (!Array.isArray(headers)) return '';

  const header = headers.find(
    h => String(h.name || '').toLowerCase() === name.toLowerCase()
  );

  return header?.value || '';
}

return items.map(item => {
  const m = item.json;

  // --------------------------------------------------
  // 1. BASIC GMAIL IDENTIFIERS
  // --------------------------------------------------

  const gmailMessageId =
    m.id ||
    m.messageId ||
    m.gmail_message_id ||
    '';

  const gmailThreadId =
    m.threadId ||
    m.thread_id ||
    m.gmail_thread_id ||
    '';

  // --------------------------------------------------
  // 2. SUBJECT / FROM / TO
  // --------------------------------------------------

  const subject =
    m.subject ||
    m.Subject ||
    getHeader(m.headers, 'Subject') ||
    '';

  const from =
    m.from ||
    m.From ||
    getHeader(m.headers, 'From') ||
    '';

  const to =
    m.to ||
    m.To ||
    getHeader(m.headers, 'To') ||
    '';

  // --------------------------------------------------
  // 3. MESSAGE CONTENT
  // --------------------------------------------------

  const snippet =
    m.snippet ||
    m.Snippet ||
    '';

  const body =
    m.textPlain ||
    m.text ||
    m.body ||
    m.textHtml ||
    '';

  const internalDate =
    m.internalDate ||
    m.internal_date ||
    '';

  // --------------------------------------------------
  // 4. DETERMINE MESSAGE DIRECTION
  // --------------------------------------------------

  const fromLower = String(from).toLowerCase();

  const isSentByMe =
    fromLower.includes(MY_EMAIL.toLowerCase());

  // --------------------------------------------------
  // 5. DELIVERY FAILURE DETECTION
  // --------------------------------------------------

  const combinedText = (
    String(subject) +
    ' ' +
    String(snippet) +
    ' ' +
    String(body) +
    ' ' +
    String(from)
  ).toLowerCase();

  const isDeliveryFailure =
    combinedText.includes('address not found') ||
    combinedText.includes('message wasn\'t delivered') ||
    combinedText.includes('message was not delivered') ||
    combinedText.includes('couldn\'t be delivered') ||
    combinedText.includes('could not be delivered') ||
    combinedText.includes('rejected your message') ||
    combinedText.includes('delivery status notification') ||
    combinedText.includes('undeliverable') ||
    combinedText.includes('mailer-daemon') ||
    combinedText.includes('postmaster') ||
    combinedText.includes('550 5.1.1') ||
    combinedText.includes('550 5.') ||
    combinedText.includes('delivery failure');

  // --------------------------------------------------
  // 6. INCOMING MESSAGE
  // --------------------------------------------------

  const isIncoming =
    !isSentByMe;

  // --------------------------------------------------
  // 7. FINAL CLEAN OUTPUT
  // --------------------------------------------------

  return {
    json: {
      gmail_message_id: gmailMessageId,
      gmail_thread_id: gmailThreadId,

      subject: subject,
      from: from,
      to: to,

      snippet: snippet,
      body: body,
      internal_date: internalDate,

      is_sent: isSentByMe,
      is_incoming: isIncoming,
      is_delivery_failure: isDeliveryFailure
    }
  };
});

const aiItems = $input.all();

// Get the original Gmail data from the FIRST Code node
const sourceItems = $('Code in JavaScript').all();

return aiItems.map((item, index) => {
  const source = sourceItems[index]?.json || {};

  let result = {};

  try {
    result =
      typeof item.json.output === 'string'
        ? JSON.parse(item.json.output)
        : item.json.output;
  } catch (error) {
    result = {
      classification: 'NO_RESPONSE',
      action_required: false,
      pause_follow_up: false,
      reason: 'AI output could not be parsed'
    };
  }

  return {
    json: {
      gmail_message_id: source.gmail_message_id || '',
      gmail_thread_id: source.gmail_thread_id || '',
      subject: source.subject || '',
      from: source.from || '',
      to: source.to || '',
      snippet: source.snippet || '',
      body: source.body || '',
      internal_date: source.internal_date || '',

      is_sent: source.is_sent ?? false,
      is_incoming: source.is_incoming ?? false,
      is_delivery_failure: source.is_delivery_failure ?? false,

      classification: result.classification || 'NO_RESPONSE',
      action_required: result.action_required ?? false,
      pause_follow_up: result.pause_follow_up ?? false,
      reason: result.reason || ''
    }
  };
});

const items = $input.all();

const groups = new Map();

for (const item of items) {
  const data = item.json;

  const threadId = data.gmail_thread_id;

  // Skip records without a thread ID
  if (!threadId) {
    continue;
  }

  if (!groups.has(threadId)) {
    groups.set(threadId, []);
  }

  groups.get(threadId).push(data);
}

const results = [];

for (const [threadId, messages] of groups.entries()) {

  // Sort oldest → newest
  messages.sort((a, b) => {
    const dateA = Number(a.internal_date || 0);
    const dateB = Number(b.internal_date || 0);
    return dateA - dateB;
  });

  // Find incoming messages only
  const incomingMessages = messages.filter(
    message => message.is_incoming === true
  );

  // Find meaningful responses
  const meaningfulResponses = incomingMessages.filter(message =>
    [
      'INTERVIEW',
      'ASSESSMENT',
      'REJECTION',
      'HR_RESPONSE',
      'ACTION_REQUIRED',
      'DELIVERY_FAILURE'
    ].includes(message.classification)
  );

  // Find acknowledgements
  const acknowledgements = incomingMessages.filter(
    message => message.classification === 'ACKNOWLEDGEMENT'
  );

  let finalMessage = null;

  /*
   * Priority:
   * 1. Meaningful company response
   * 2. Delivery failure
   * 3. Acknowledgement
   * 4. No response
   */

  if (meaningfulResponses.length > 0) {

    // Use the newest meaningful response
    finalMessage =
      meaningfulResponses[meaningfulResponses.length - 1];

  } else if (acknowledgements.length > 0) {

    // Only acknowledgement exists
    finalMessage =
      acknowledgements[acknowledgements.length - 1];

  } else {

    // No meaningful incoming response
    finalMessage = {
      classification: 'NO_RESPONSE',
      action_required: false,
      pause_follow_up: false,
      reason: 'No meaningful company response found'
    };
  }

  results.push({
    json: {
      gmail_thread_id: threadId,

      // Original application information
      subject:
        messages[0].subject || '',

      from:
        messages[0].from || '',

      to:
        messages[0].to || '',

      gmail_message_id:
        messages[0].gmail_message_id || '',

      // Final thread decision
      classification:
        finalMessage.classification,

      action_required:
        finalMessage.action_required,

      pause_follow_up:
        finalMessage.pause_follow_up,

      reason:
        finalMessage.reason || '',

      // Useful tracking information
      total_messages:
        messages.length,

      incoming_messages:
        incomingMessages.length,

      has_acknowledgement:
        acknowledgements.length > 0,

      has_meaningful_response:
        meaningfulResponses.length > 0
    }
  });
}

return results;

const items = $input.all();

return items.map(item => {
  const app = item.json;

  const followupCount = Number(app.followup_count || 0);
  const attemptNumber = followupCount + 1;

  const followupDays = {
    1: 3,
    2: 7,
    3: 14
  };

  return {
    json: {
      ...app,
      followup_attempt: attemptNumber,
      followup_days: followupDays[attemptNumber] || null,
      can_followup: attemptNumber <= 3
    }
  };
});

const items = $input.all();

return items.map(item => {
  const raw = item.json.output || '';

  let parsed;

  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    return {
      json: {
        ai_valid: false,
        reason: 'Invalid JSON returned by AI',
        subject: '',
        body: ''
      }
    };
  }

  return {
    json: {
      application_id: parsed.application_id,
      gmail_thread_id: parsed.gmail_thread_id,
      followup_attempt: parsed.followup_attempt,
      company: parsed.company,
      role: parsed.role,
      recipient_email: parsed.recipient_email,
      recipient_name: parsed.recipient_name,

      subject: parsed.subject || '',
      body: parsed.body || '',

      ai_valid:
        parsed.ai_valid === true &&
        Boolean(parsed.application_id) &&
        Boolean(parsed.gmail_thread_id) &&
        Boolean(parsed.company) &&
        Boolean(parsed.role) &&
        Boolean(parsed.subject) &&
        Boolean(parsed.body),

      reason: parsed.reason || ''
    }
  };
});

