UPDATE followups
SET
    generated_subject = '{{ $json.subject.replace(/'/g, "''") }}',
    generated_body = '{{ $json.body.replace(/'/g, "''") }}'
WHERE application_id = {{ $json.application_id }}
  AND attempt_number = {{ $json.followup_attempt }}
  AND status = 'PENDING'
RETURNING *;

